WITH exploded AS (SELECT id, customer_id, created_at, code FROM carts LATERAL VIEW OUTER EXPLODE(coupon_codes) li AS code) SELECT code, COUNT(CASE WHEN code = 'VIP' THEN 1 END) AS vip_count, COUNT(*) AS num_rows, COUNT(DISTINCT code) AS distinct_codes, COUNT_IF(code = 'VIP') AS vip_events, COUNT(*) FILTER (WHERE code = 'SPRING10') AS spring10_rows FROM exploded GROUP BY code ORDER BY vip_events DESC NULLS LAST;
